import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] 文件数 = new int[n];
        for (int i = 0; i < n; i++) {
            文件数[i] = sc.nextInt();
        }
        System.out.println("src/");
        int 合计 = 0;
        for (int i = 0; i < n; i++) {
            合计 = 合计 + 文件数[i];
            String 头 = "├─ ";
            if (i == n - 1) {
                头 = "└─ ";
            }
            System.out.println(头 + "p" + (i + 1) + "（" + 文件数[i] + " 个文件）");
        }
        System.out.println("共 " + n + " 个包，" + 合计 + " 个文件");
    }
}

